export function getSegregationFeatureSections() {
    const map = new Map();
    for (const row of segregationFeatureMatrix) {
        const list = map.get(row.section) ?? [];
        list.push(row);
        map.set(row.section, list);
    }
    return [...map.entries()].map(([title, rows]) => ({ title, rows }));
}
